<?php
$student=$this->db->where('student_id',(int)($request['student_id']??0))->get('student')->row_array();$year=get_settings('running_year');$term=get_settings('running_term');$enroll=$this->db->where(['student_id'=>(int)($request['student_id']??0),'year'=>$year,'term'=>$term])->get('enroll')->row_array();$class=!empty($enroll['class_id'])?$this->db->where('class_id',$enroll['class_id'])->get('class')->row_array():[];$section=!empty($enroll['section_id'])?$this->db->where('section_id',$enroll['section_id'])->get('section')->row_array():[];$requester=$this->db->where('admin_id',(int)($request['requested_by']??0))->get('admin')->row_array();$reviewer=!empty($request['reviewed_by'])?$this->db->where('admin_id',(int)$request['reviewed_by'])->get('admin')->row_array():[];$old_data=json_decode($request['old_data']??'[]',true);$old_data=is_array($old_data)?$old_data:[];$new_data=!empty($request['new_data'])?json_decode($request['new_data'],true):[];$new_data=is_array($new_data)?$new_data:[];$currency='₵';$status=$request['status']??'pending';
$total_old=array_sum(array_map(function($i){return (float)($i['amount']??0);},$old_data));$total_new=array_sum(array_map(function($i){return (float)($i['amount']??0);},$new_data));
