<div class="invoice-evidence">
    <div class="invoice-evidence-head"><div><h3>Invoice Modification Evidence</h3><p>Request #<?php echo (int)($request['request_id']??0); ?> · <?php echo html_escape(ucfirst($request['request_type']??'edit')); ?> · <?php echo !empty($request['created_at'])?html_escape(date('d M Y, H:i',strtotime($request['created_at']))):'—'; ?></p></div><span class="invoice-status <?php echo html_escape($status); ?>"><?php echo html_escape($status); ?></span></div>
