    <?php if(trim((string)($request['request_reason']??''))!==''): ?><div class="invoice-evidence-section"><h4>Reason for Modification</h4><div class="invoice-evidence-note"><?php echo nl2br(html_escape($request['request_reason'])); ?></div></div><?php endif; ?>
    <div class="invoice-evidence-section"><h4>Original Invoice</h4><div class="invoice-evidence-table-shell"><table class="invoice-evidence-table"><thead><tr><th>Item</th><th>Description</th><th style="text-align:right">Amount</th></tr></thead><tbody><?php if(!$old_data): ?><tr><td colspan="3">No original invoice snapshot available.</td></tr><?php else: foreach($old_data as $item): ?><tr><td><strong><?php echo html_escape($item['title']??''); ?></strong></td><td><?php echo html_escape($item['description']??''); ?></td><td style="text-align:right"><?php echo $currency.' '.number_format((float)($item['amount']??0),2); ?></td></tr><?php endforeach; endif; ?></tbody><tfoot><tr><td colspan="2" style="text-align:right">Original Total</td><td style="text-align:right"><?php echo $currency.' '.number_format($total_old,2); ?></td></tr></tfoot></table></div></div>
    <?php if(($request['request_type']??'')==='edit' && $new_data): $old_map=[];foreach($old_data as $old){$old_map[(string)($old['title']??'')]=$old;} ?><div class="invoice-evidence-section"><h4>Proposed Invoice</h4><div class="invoice-evidence-table-shell"><table class="invoice-evidence-table"><thead><tr><th>Item</th><th>Description</th><th style="text-align:right">Amount</th></tr></thead><tbody><?php foreach($new_data as $item): $title=(string)($item['title']??'');$old=$old_map[$title]??null;$changed=!$old||abs((float)($old['amount']??0)-(float)($item['amount']??0))>.009; ?><tr><td><strong><?php echo html_escape($title); ?></strong><?php if(!$old): ?> <span class="invoice-change">NEW</span><?php elseif($changed): ?> <span class="invoice-change">CHANGED</span><?php endif; ?></td><td><?php echo html_escape($item['description']??($old['description']??'')); ?></td><td style="text-align:right"><?php if($changed&&$old): ?><span style="color:#94a3b8;text-decoration:line-through;margin-right:6px"><?php echo number_format((float)$old['amount'],2); ?></span><?php endif; ?><?php echo $currency.' '.number_format((float)($item['amount']??0),2); ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><td colspan="2" style="text-align:right">Proposed Total</td><td style="text-align:right"><?php echo $currency.' '.number_format($total_new,2); ?></td></tr></tfoot></table></div></div><?php endif; ?>
    <?php if($status!=='pending'&&$status!=='processing'): ?><div class="invoice-review">Decision: <?php echo html_escape(ucfirst($status)); ?><?php if($reviewer): ?> by <?php echo html_escape($reviewer['name']); ?><?php endif; ?><?php if(!empty($request['reviewed_at'])): ?> · <?php echo html_escape(date('d M Y, H:i',strtotime($request['reviewed_at']))); ?><?php endif; ?></div><?php endif; ?>
</div>
